using System;
using System.IO;
using System.Reflection;
namespace PZ3D {
 static class ReticleSettingsTests {
  public static void Run(){var t=typeof(Engine).Assembly.GetType("PZ3D.ReticleSettings");if(t==null)throw new Exception("FAIL: configurable native aim fallback missing");var s=Activator.CreateInstance(t);string props=(string)t.GetMethod("Properties").Invoke(s,new object[]{"E:\\Steam\\ISeeThem.jar"});Check(props.Contains("aim.mode=native")&&props.Contains("aim.key=0"),"default original aiming and unbound shortcut");t.GetProperty("KeyText").SetValue(s,"CTRL+F8",null);props=(string)t.GetMethod("Properties").Invoke(s,new object[]{"E:\\Steam\\ISeeThem.jar"});Check(props.Contains("aim.key=66")&&props.Contains("aim.ctrl=true")&&props.Contains("shoot.jar=E:\\\\Steam\\\\ISeeThem.jar"),"shortcut converts to game scan code and escapes author path");t.GetProperty("KeyText").SetValue(s,"CTRL+UNKNOWN",null);bool rejected=false;try{t.GetMethod("Properties").Invoke(s,new object[]{"source"});}catch(TargetInvocationException){rejected=true;}Check(rejected,"unsupported shortcut cannot silently become another key");Bridge();MetadataRepair();}
  static void MetadataRepair(){string game=Engine.DetectGame();if(game.Length==0)return;string source=Path.GetFullPath(Path.Combine(game,"..","..","workshop","content","108600",ShootClient.Item.ToString()));if(!Directory.Exists(source))return;string root=Path.Combine(LauncherTestPaths.Root,"orange-addon-metadata-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\"]}");File.WriteAllText(e.Mods,"mods\n{\nmod = ZombieBuddy,\nmod = Viewpoint,\nmod = ShootToThrillMultiplayer,\n}\n");File.WriteAllText(Path.Combine(e.Game,"ZombieBuddy.jar"),"fixture");File.WriteAllText(Path.Combine(e.Game,"zbNative.dll"),"fixture");var bridge=new PresentationBridge();bridge.Enable(e,source);string info=Path.Combine(Path.GetDirectoryName(e.Mods),PresentationBridge.Id,"42","mod.info");File.WriteAllText(info,"");bridge.Enable(e,source);Check(File.ReadAllText(info).Contains("javaPkgName=orange.ads"),"corrupt addon metadata is repaired rather than reported already current");}
  static void Bridge(){string game=Engine.DetectGame();if(game.Length==0)return;string source=Path.GetFullPath(Path.Combine(game,"..","..","workshop","content","108600",ShootClient.Item.ToString()));if(!File.Exists(Path.Combine(source,"mods",ShootClient.Id,"42","media","java","client","ISeeThem.jar")))return;string root=Path.Combine(LauncherTestPaths.Root,"orange-reticle-install-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\",\"-Xmx12345m\"]}");File.WriteAllText(e.Mods,"mods\n{\nmod = ZombieBuddy,\nmod = Viewpoint,\nmod = ShootToThrillMultiplayer,\n}\n");File.WriteAllText(Path.Combine(e.Game,"ZombieBuddy.jar"),"fixture");File.WriteAllText(Path.Combine(e.Game,"zbNative.dll"),"fixture");var bridge=new PresentationBridge();bridge.Enable(e,source);Check(!File.ReadAllText(e.Config).Contains("-javaagent:OrangeShootPresentation.jar")&&File.ReadAllText(e.Mods).Contains("mod = OrangeShootPresentation,"),"bridge uses Buddy addon instead of startup javaagent");string file=Path.Combine(Path.GetDirectoryName(e.Mods),"OrangeShootPresentation","42","media","java","client",PresentationBridge.ConfigName);Check(File.ReadAllText(file).Contains("aim.mode=native")&&File.ReadAllText(file).Contains("aim.key=0"),"installation writes native fallback default into actual bridge config");new ReticleSettings{KeyText="CTRL+F8"}.Save(e.Data);bridge.Enable(e,source);Check(bridge.Enabled(e)&&File.ReadAllText(file).Contains("aim.key=66")&&File.ReadAllText(e.Config).Contains("-Xmx12345m"),"reinstall applies shortcut to installed bridge while preserving memory arguments");string before=File.ReadAllText(file);File.WriteAllText(Path.Combine(e.Data,"aim-fallback.json"),"{\"KeyText\":\"INVALID\",\"StartNative\":true}");bool refused=false;try{bridge.Enable(e,source);}catch{refused=true;}Check(refused&&bridge.Enabled(e)&&File.ReadAllText(file)==before,"invalid preferences refuse replacement before removing existing bridge");}
  static void Check(bool ok,string text){if(!ok)throw new Exception("FAIL: "+text);Console.WriteLine("PASS: "+text);}
 }
}
